"""Generate the frozen tools_picking_drill trajectory."""
from rcb_robolab import Session
import numpy as np
import math
import traceback

s = Session('tools_picking_drill', instance='/app/instance.json')
p = s.primitives()

def qmul(a, b):
    w, x, y, z = a
    v, r, t, u = b
    return np.array([w*v-x*r-y*t-z*u, w*r+x*v+y*u-z*t,
                     w*t-x*u+y*v+z*r, w*u+x*t-y*r+z*v])

def tilted(yaw, angle):
    return qmul(np.array([math.cos(angle/2), 0, math.sin(angle/2), 0]),
                p['top_down_quat'](yaw))

def move(pos, quat, speed=.18, max_steps=95):
    try:
        p['move_ee'](pos, quat, speed=speed, max_steps=max_steps,
                     tol=.012, rot_tol=.12)
    except Exception:
        err = float(np.linalg.norm(s.ee_pose()[0] - np.array(pos)))
        if err > .025:
            raise

def run():
    s.reset()
    yaw = p['yaw_for_closing_dir']([1, 0])
    q = tilted(yaw, -.7)
    y, z = -.29, .14
    s.record_start()
    try:
        p['close_gripper'](20)
        move([.86, y, .29], q, .20, max_steps=80)
        try:
            move([.86, y, z], q, .09, max_steps=65)
        except Exception:
            pass
        for x in [.82, .78, .74, .70, .66, .62, .59, .56, .53]:
            try:
                move([x, y, z], q, .07, max_steps=45)
            except Exception:
                pass
            if s.status()['success']:
                break
        for x, zz in [(.50, .18), (.46, .22)]:
            try:
                move([x, y, zz], q, .09, max_steps=60)
            except Exception:
                pass
        p['open_gripper'](15)
        try:
            move([.43, y, .34], q, .14, max_steps=60)
        except Exception:
            pass
        p['hold'](30)
    finally:
        actions = s.record_stop()
        print('status', s.status(), 'actions', len(actions), flush=True)
        if s.status()['success']:
            s.save_trajectory(actions, '/app/output/trajectory.npz')
            print('saved /app/output/trajectory.npz', flush=True)
        else:
            raise RuntimeError('Trajectory did not reach the success predicate')

if __name__ == '__main__':
    run()
